mapper.select:
SELECT vt.id, vt.visitor_id, vt.appointment_id, vt.gate_id, vt.area_id, vt.action, vt.recorded_at, vt.stay_duration_minutes, vt.departure_status, v.name AS visitor_name, g.gate_name AS gate_name, a.area_name AS area_name FROM visitor_trajectory vt LEFT JOIN visitor v ON vt.visitor_id = v.id LEFT JOIN gate g ON vt.gate_id = g.id LEFT JOIN area a ON vt.area_id = a.id
AND vt.visitor_id = #{visitorId} AND vt.appointment_id = #{appointmentId}
ORDER BY vt.recorded_at ASC
